import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Ajustar o brilho leva só alguns minutos. Você envia a foto, arrasta um controle, confere o resultado e baixa a versão mais clara.</p>\n<p>Este passo a passo cobre o processo inteiro. Você vai ver o controle, as predefinições rápidas, os modos de comparação e as configurações de exportação que mantêm o resultado natural.</p>\n<p>No final, você vai conseguir corrigir um retrato escuro, uma paisagem sem graça ou uma captura de tela turva em qualquer dispositivo. Guarde a foto original até conferir o resultado.</p>\n<h2 id=\"before-you-start\">Antes de começar: avalie o quanto está escuro</h2>\n<p>Olhe a foto antes de abrir a ferramenta. Ela está levemente escura, bem escura ou escura só numa área? A resposta diz quanto clareamento ela precisa.</p>\n<p>Uma foto levemente escura precisa de 10 a 15 por cento. Uma bem escura pode precisar de 30 por cento ou mais, mas movimentos grandes correm o risco de estourar os realces.</p>\n<p>Confira se a foto também está chapada ou sem graça. Uma foto escura e chapada precisa de brilho e contraste juntos, então planeje as duas edições, não só uma.</p>\n<p>Abra o <a href=\"/pt/ajustar-brilho-da-imagem/\">Ajustar brilho da foto</a> no seu navegador. Tudo roda localmente, então sua foto nunca é enviada para um servidor.</p>\n<h2 id=\"step-by-step\">Ajuste o brilho em cinco passos</h2>\n<p>O processo é o mesmo para uma foto, uma captura de tela ou um documento digitalizado. Envie, ajuste, compare, exporte e confira o download.</p>\n<p>Leve o controle com calma. Movimentos pequenos fazem uma grande diferença, e a prévia mostra exatamente quando a foto fica certa.</p>\n<ol>\n<li>Envie sua imagem arrastando-a para a área de envio, escolhendo-a no seu dispositivo ou colando uma captura de tela com Ctrl+V.</li>\n<li>Arraste o controle Nível de brilho para a direita para clarear ou para a esquerda para escurecer, observando a prévia ao vivo.</li>\n<li>Teste um ajuste pronto para ver o resultado em um clique e depois afine com o controle se estiver perto, mas não exato.</li>\n<li>Use os modos Depois, Antes, Comparação dividida ou Comparação em tela cheia para conferir o resultado contra a original.</li>\n<li>Escolha o formato e a qualidade de exportação e clique em Baixar para salvar a imagem ajustada.</li>\n</ol>\n<p>Abra o arquivo baixado uma vez antes de usá-lo. Confirme que a foto parece iluminada naturalmente e que nenhuma área clara virou branco.</p>\n<h2 id=\"using-the-slider\">Como usar o controle de brilho</h2>\n<p>O controle vai de valores negativos a positivos, com zero significando nenhuma mudança. Mover para a direita clareia a imagem, e mover para a esquerda escurece.</p>\n<p>Arraste devagar e observe a prévia. A atualização ao vivo mostra exatamente como a imagem reage, então você pode parar no ponto em que a foto fica certa.</p>\n<p>Movimentos pequenos são melhores que os grandes. Uma mudança de 10 a 15 por cento costuma bastar, e movimentos maiores estouram os realces rapidinho.</p>\n<p>A ferramenta mostra sua foto em mais 15 por cento logo depois do envio. Esse ponto de partida já dá uma ideia imediata de como fica um clareamento moderado.</p>\n<h2 id=\"using-quick-presets\">Como usar as predefinições rápidas</h2>\n<p>A ferramenta inclui predefinições rápidas que aplicam valores comuns de brilho num só clique. São um jeito rápido de testar níveis diferentes sem arrastar o controle.</p>\n<p>Clique numa predefinição e olhe a prévia. Se o resultado estiver perto, mas não exato, ajuste com o controle a partir daquele ponto.</p>\n<p>Use as predefinições para comparar opções rapidinho. Uma predefinição em mais 15 por cento ao lado de uma em mais 30 por cento mostra quanto clareamento a foto aguenta.</p>\n<p>Para um lote de fotos parecidas, a mesma predefinição mantém os resultados consistentes. Um conjunto de fotos escuras de interior, todas clareadas na mesma medida, parece uma série.</p>\n<h2 id=\"using-compare-modes\">Como usar os modos de comparação</h2>\n<p>Os modos de comparação mostram a original e a versão editada juntas. O modo Depois mostra a imagem clareada, e o modo Antes mostra a original.</p>\n<p>A comparação dividida é a mais útil para o trabalho de brilho. Ela mostra as duas versões lado a lado com uma linha clara entre elas, para você ver exatamente o que mudou.</p>\n<p>A comparação em tela cheia mostra a foto maior. É o melhor jeito de avaliar uma foto clareada, porque a imagem em tamanho real mostra detalhes que uma prévia pequena esconde.</p>\n<p>Confira a comparação antes de cada download. Uma olhada rápida pega um clareamento excessivo que uma prévia pequena poderia esconder.</p>\n<h2 id=\"brightening-a-dark-photo\">Como clarear uma foto escura</h2>\n<p>Envie a foto escura e arraste o controle para mais 15 por cento. Confira a prévia: o assunto deve ficar bem visível, e as áreas claras ainda devem mostrar detalhe.</p>\n<p>Se a foto continuar escura demais, aumente o controle em passos pequenos de 5 por cento. Cada passo adiciona um pouco mais de luz, e a prévia mostra quando parar.</p>\n<p>Observe os realces enquanto ajusta. A testa, o céu e qualquer superfície branca vão estourar primeiro, e uma foto com manchas brancas fica pior que uma escura.</p>\n<p>Se a foto parecer chapada depois de clarear, adicione contraste. Abra o <a href=\"/pt/ajustar-contraste-da-imagem/\">ajustar o contraste da foto</a> e aplique um pequeno reforço para restaurar a profundidade.</p>\n<h2 id=\"darkening-a-bright-photo\">Como escurecer uma foto clara</h2>\n<p>Arraste o controle para a esquerda para uma foto clara demais. Valores negativos, como menos 15 ou menos 30 por cento, aprofundam as sombras e restauram a riqueza.</p>\n<p>Confira as sombras enquanto escurece. Elas devem ganhar profundidade sem virar manchas pretas sólidas, sem detalhe nenhum.</p>\n<p>Escurecer também ajuda quando uma foto vai ficar atrás de um texto. Uma imagem escurecida deixa o texto branco legível, o que combina com slides, cartazes e gráficos de redes sociais.</p>\n<p>Para uma foto clara demais no céu e escura demais no primeiro plano, aceite um meio-termo. O brilho move tudo junto, então nenhuma direção sozinha corrige as duas áreas.</p>\n<h2 id=\"fixing-a-screenshot\">Como corrigir uma captura de tela escura</h2>\n<p>Cole uma captura de tela direto com Ctrl+V para pular a etapa de salvar. A imagem aparece no editor na hora, pronta para clarear.</p>\n<p>Aumente o brilho até o texto ficar claro e o fundo branco. Um documento com fundo branco limpo e texto escuro é fácil de ler e de imprimir.</p>\n<p>Cuidado com o ruído nas áreas escuras. Uma captura muito clareada pode mostrar padrões de blocos fracos, principalmente num JPEG que já estava comprimido.</p>\n<p>Exporte capturas de tela em PNG. O formato sem perda mantém o texto pequeno nítido, o que importa quando a captura mostra uma configuração ou uma mensagem de erro.</p>\n<h2 id=\"previewing\">Prévia antes de baixar</h2>\n<p>Confira sempre a prévia antes de baixar. Veja se a foto parece iluminada naturalmente, se nenhuma área clara virou branco e se o assunto está bem visível.</p>\n<p>Use a comparação dividida para conferir a mudança. Ela mostra a original e a versão editada lado a lado, para você ver exatamente o que o brilho fez.</p>\n<p>Dê zoom nas áreas claras em tamanho real. Um céu ou uma testa que parece bom numa prévia pequena pode estar estourado quando visto grande.</p>\n<p>Se o resultado parecer estourado, reduza o controle em 5 por cento e confira de novo. Pequenas reduções costumam restaurar o detalhe sem deixar a foto escura de novo.</p>\n<h2 id=\"choosing-export-format\">Como escolher o formato de exportação</h2>\n<p>Escolha JPG para fotos que você planeja compartilhar. Ele mantém os arquivos pequenos e funciona em todo lugar, e uma qualidade alta mantém a foto clareada limpa.</p>\n<p>Escolha PNG para capturas de tela e gráficos com texto. O PNG não tem perda, então as bordas das letras ficam nítidas, e ele preserva a transparência quando você precisa.</p>\n<p>Escolha WebP quando quiser arquivos pequenos com boa qualidade. Ele funciona bem para imagens de web, embora alguns sistemas mais antigos ainda rejeitem o formato.</p>\n<p>Lembre que o controle de qualidade some para PNG, porque o PNG não tem perda e não tem ajuste de qualidade. Isso é comportamento normal, não um problema da ferramenta.</p>\n<h2 id=\"adjusting-on-mobile\">Como ajustar o brilho no celular ou no tablet</h2>\n<p>A ferramenta funciona em telas de toque, então dá para corrigir uma foto escura no próprio celular que a tirou. Envie da sua galeria, arraste o controle com o dedo e baixe o resultado.</p>\n<p>Arrastar um controle com o dedo é menos preciso que com o mouse. Use as predefinições rápidas para valores exatos e depois ajuste com arrastes pequenos.</p>\n<p>Confira a prévia em tamanho real antes de baixar. Uma mudança de brilho que parece boa na tela pequena do celular pode ficar forte demais quando vista no computador.</p>\n<p>Os arquivos baixados vão para a sua pasta de downloads. De lá, você pode compartilhar a foto clareada direto num aplicativo de conversa, num e-mail ou num post de rede social.</p>\n<h2 id=\"troubleshooting\">Solução de problemas comuns de brilho</h2>\n<p>Se a foto parecer estourada, o controle está alto demais. Reduza em passos pequenos até os realces mostrarem detalhe de novo e depois confira as sombras.</p>\n<p>Se a foto continuar escura depois de clarear, a original pode ser escura demais para salvar. Uma foto quase preta não dá para corrigir só com brilho, e refazer a foto é a melhor opção.</p>\n<p>Se aparecer ruído nas sombras, o clareamento está forte demais para a fonte. Reduza o controle e aceite uma foto levemente mais escura, ou comece de uma original melhor.</p>\n<p>Se a prévia parecer diferente do download, confira o formato e a qualidade de exportação. Uma qualidade JPG baixa pode suavizar a imagem inteira, inclusive as áreas claras.</p>\n<h2 id=\"brightness-plus-contrast\">Brilho mais contraste: a dupla comum</h2>\n<p>Uma foto escura e chapada precisa de brilho e contraste juntos. Clareie primeiro para levantar o nível geral e depois adicione contraste para restaurar a profundidade.</p>\n<p>Use o <a href=\"/pt/ajustar-contraste-da-imagem/\">ajustar o contraste da foto</a> depois de clarear, quando a imagem parecer cinza e sem vida. Um pequeno reforço de contraste traz de volta as sombras e os realces.</p>\n<p>Faça os passos em ordem: brilho primeiro, depois contraste. Inverter pode deixar o ajuste de contraste mais difícil de avaliar, porque a imagem continua escura.</p>\n<p>Confira a comparação depois de cada passo. A comparação dividida mostra exatamente o que cada ajuste fez, para você parar quando a foto ficar certa.</p>\n<h2 id=\"saving-settings\">Como guardar seus ajustes para a próxima vez</h2>\n<p>Anote o valor de brilho que funcionou para um conjunto de fotos parecidas. Uma anotação curta, como fotos de interior mais 20 por cento, evita adivinhar na próxima vez.</p>\n<p>Para um lote de fotos tiradas com a mesma luz, use o mesmo valor para todas. Um brilho consistente num conjunto parece profissional, enquanto valores misturados parecem aleatórios.</p>\n<p>Guarde os arquivos originais. Um valor de brilho que funciona para uma foto pode não servir para outra, e a original permite testar outro nível sem dano extra.</p>\n<p>Revise suas anotações de vez em quando. Conforme sua câmera e sua iluminação melhoram, os valores de brilho de que você precisa vão mudar, e anotações antigas podem enganar.</p>\n<h2 id=\"quick-tips\">Dicas rápidas para um brilho melhor</h2>\n<p>Clareie em passos pequenos. Uma mudança de 5 por cento por vez dá controle, enquanto um salto grande pode passar do valor certo antes de você perceber.</p>\n<p>Confira os realces, não só as sombras. Uma foto está clareada demais quando as áreas claras perdem detalhe, mesmo que as áreas escuras pareçam boas.</p>\n<p>Use a comparação sempre. Uma olhada rápida na original ao lado da edição pega erros que uma prévia pequena esconde.</p>\n<p>Guarde a foto original sem edições. Depois que uma mudança de brilho é aplicada numa exportação, não dá para desfazê-la a partir daquele arquivo.</p>\n<h2 id=\"brightening-for-presentation\">Como clarear uma foto para uma apresentação</h2>\n<p>Uma foto usada num slide precisa ser clara o bastante para ver do fundo da sala. Uma imagem escura numa tela grande parece turva, enquanto uma bem iluminada é legível.</p>\n<p>Clareie fotos de slide um pouco mais do que faria para um feed. Projetores desbotam as cores e reduzem o brilho, então uma foto que parece boa no laptop pode parecer escura quando projetada.</p>\n<p>Confira a foto no projetor de verdade, se puder. Um slide de teste mostra se o brilho se mantém na sala, onde a luz é bem diferente da sua mesa.</p>\n<p>Mantenha o clareamento uniforme no slide. Uma foto clara num canto e escura em outro distrai o público das palavras em cima dela.</p>\n<h2 id=\"brightening-old-scans\">Como clarear fotos antigas digitalizadas</h2>\n<p>Fotos antigas digitalizadas costumam ser escuras e desbotadas. O tempo apaga a impressão, o scanner lê os tons errado, e o resultado é uma imagem cinza e turva que precisa de um reforço.</p>\n<p>Aumente o brilho em passos pequenos e observe os rostos. O objetivo é uma foto parecida com a impressão original quando era nova, não uma versão estourada dela.</p>\n<p>Digitalizações antigas muitas vezes precisam de contraste além de brilho. A impressão desbotada tem pouca faixa tonal, então um reforço de brilho mais um pequeno aumento de contraste restaura a profundidade.</p>\n<p>Trabalhe a partir da melhor digitalização que tiver. Uma digitalização de alta resolução clareia muito melhor que uma de baixa resolução, porque há mais detalhe para a edição revelar.</p>\n<p>Para a comparação, leia <a href=\"/pt/blog/brilho-vs-exposicao-vs-contraste/\">Brilho, exposição e contraste: qual a diferença?</a>. Para a visão geral, veja <a href=\"/pt/blog/como-clarear-foto-escura/\">Como clarear foto escura: guia completo</a>, e para corrigir o contraste chapado depois de clarear, experimente o <a href=\"/pt/ajustar-contraste-da-imagem/\">ajustar o contraste da foto</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Como clareio uma foto no celular?","answer":"Abra a ferramenta de ajuste de brilho da foto no navegador do celular, envie a foto da sua galeria e arraste o controle para a direita com o dedo. Use um ajuste pronto para um valor exato, confira a comparação e baixe o resultado."},{"question":"Qual valor de brilho devo usar para uma foto escura de interior?","answer":"Comece em mais 15 por cento, que é o valor da prévia da ferramenta, e aumente em passos de 5 por cento até o assunto ficar bem visível. A maioria das fotos de interior precisa de 15 a 30 por cento. Pare antes que as áreas claras, como janelas ou lâmpadas, virem branco."},{"question":"Dá para escurecer uma foto clara demais?","answer":"Sim. Arraste o controle para a esquerda, para valores negativos, como menos 15 ou menos 30 por cento. Escurecer aprofunda as sombras e restaura a riqueza de uma foto superexposta. Confira as sombras para não virarem manchas pretas sólidas."},{"question":"Por que minha foto clareada mostra ruído granulado?","answer":"Clarear revela o ruído que estava escondido nas sombras, e a compressão JPEG piora. Reduza o controle e aceite uma foto levemente mais escura, ou comece de uma original melhor, tirada com boa luz. Um reforço leve mostra bem menos ruído que um forte."},{"question":"Devo ajustar o brilho antes ou depois do contraste?","answer":"Brilho primeiro, depois contraste. Clarear levanta o nível geral, e o contraste restaura a profundidade que o clareamento pode tirar. Fazer nessa ordem deixa cada ajuste mais fácil de avaliar na comparação."},{"question":"Dá para desfazer uma mudança de brilho depois de baixar?","answer":"Não a partir do arquivo baixado, pois a mudança é aplicada na exportação. Guarde a foto original para testar outro nível de brilho. Na ferramenta, use a opção de redefinir para voltar a zero antes de baixar."}];
